contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount1, uint256 amount2, uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0) + (amount2)); require(amount2 <= 1000000000000000000000000000000);
        require(amount1 > 0);
        require(address(this).balance >= amount1);
        // fund c with amount1 via receive (top-level, plain statement)
        c.multiplicate{value: 0}(address(this)); if (__ESBMC_reverted()) return;
        c.withdraw(); if (__ESBMC_reverted()) return;
        // fund via receive using Command to self is heavy; instead send Ether by calling multiplicate with small value
        uint256 balBefore = address(c).balance;
        bool reverted;
        c.multiplicate{value: amount2}(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        if (!reverted) {
            require(balBefore <= amount2);
        }
        assert(reverted || (address(c).balance == 0 && balBefore <= amount2));
    }
    receive() external payable {}
}

