pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(uint256 amount1, uint256 amount2, uint256 dummy) internal {
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount1 > 0);
        vm.assume(address(this).balance >= amount1);
        try c.multiplicate{value: 0}(address(this)) {} catch { return; }
        try c.withdraw() {} catch { return; }
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.multiplicate{value: amount2}(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            require(balBefore <= amount2);
        }
        assertTrue(reverted || (address(c).balance == 0 && balBefore <= amount2));
    }

    function testFuzz_run(uint256 amount1, uint256 amount2, uint256 dummy) public {
        _run(amount1, amount2, dummy);
    }

    receive() external payable {}
}
